import fs from 'fs';
const types={}, roles={}, blocks={}; let sample=null, sampleRes=null;
for (const f of fs.readdirSync('/tmp/threads')) {
 for (const line of fs.readFileSync('/tmp/threads/'+f,'utf8').split('\n')) { if(!line.trim()) continue; const b=JSON.parse(line);
  for (const w of b.writes) { types[w.type]=(types[w.type]||0)+1;
   if (w.type==='entry') { const v=w.value; const keys=Object.keys(v).join(','); types['entrykeys:'+keys]=(types['entrykeys:'+keys]||0)+1;
    for (const m of (v.model||[])) { roles[m.role]=(roles[m.role]||0)+1; if (Array.isArray(m.content)) for (const c of m.content){ const k=m.role+':'+c.type+':'+(c.name||''); blocks[k]=(blocks[k]||0)+1; if(c.type==='toolCall'&&c.name==='typescript'&&!sample) sample=c; }
     if(m.role==='toolResult'&&m.toolName==='typescript'&&!sampleRes) sampleRes=m; }
   } } } }
console.log(JSON.stringify({types,roles,blocks},null,1)); console.log(JSON.stringify(sample).slice(0,1500)); console.log(JSON.stringify(sampleRes).slice(0,2500));
